CREATE OR REPLACE FUNCTION public.register_as_broker(_display_name text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); lic text; nm text; ph text; em text; lead uuid; warning text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0)); IF NOT public.publisher_sms_verified() THEN RAISE EXCEPTION 'broker_sms_verification_required'; END IF; IF NOT public.partner_can_view_closing(uid) OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role IN ('agent','lead_agent','managing_broker')) THEN IF NOT EXISTS(SELECT 1 FROM public.broker_upgrade_requests WHERE user_id=uid AND status='approved') THEN RAISE EXCEPTION 'broker_identity_approval_required'; END IF; END IF; SELECT license_number INTO lic FROM public.broker_license_verifications WHERE user_id=uid AND source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6' AND source_updated_at>now()-interval '7 days'; IF lic IS NULL OR NOT public.official_license_exists(lic) THEN RAISE EXCEPTION 'broker_license_registry_verification_required'; END IF; PERFORM public.ensure_profile_row(uid); UPDATE public.profiles SET broker_license_number=lic WHERE id=uid; INSERT INTO public.user_roles(user_id,role) VALUES(uid,'agent') ON CONFLICT(user_id,role) DO NOTHING; UPDATE public.profiles SET full_name=public.official_broker_name(uid,lic), locked_broker_name=public.official_broker_name(uid,lic) WHERE id=uid; SELECT full_name,phone,email INTO nm,ph,em FROM public.profiles WHERE id=uid; IF NULLIF(regexp_replace(COALESCE(ph,''),'\D','','g'),'') IS NOT NULL THEN BEGIN lead:=public.ensure_rita_crm_contact(nm,ph,em,'הרשמת מתווך לאפליקציה','app_registration',uid); EXCEPTION WHEN OTHERS THEN warning:=SQLERRM; END; ELSE warning:='registration_phone_missing'; END IF; RETURN jsonb_build_object('ok',true,'user_id',uid,'role','agent','lead_id',lead,'warning',warning); END; $$;
CREATE OR REPLACE FUNCTION public.protect_locked_broker_name() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.locked_broker_name IS NOT NULL THEN NEW.locked_broker_name:=OLD.locked_broker_name; NEW.full_name:=OLD.locked_broker_name; ELSIF NEW.locked_broker_name IS NOT NULL THEN IF auth.role() IS DISTINCT FROM 'service_role' AND (NOT public.publisher_sms_verified() OR NEW.id IS DISTINCT FROM auth.uid() OR NOT public.partner_can_view_closing(NEW.id) OR NEW.locked_broker_name IS DISTINCT FROM public.official_broker_name(NEW.id,NEW.broker_license_number)) THEN RAISE EXCEPTION 'server_identity_required'; END IF; NEW.full_name:=NEW.locked_broker_name; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.submit_broker_upgrade_request() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); v record; c record; request_id uuid; auto_approve boolean; outcome text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF; IF NOT public.publisher_sms_verified() THEN RAISE EXCEPTION 'broker_sms_verification_required'; END IF; SELECT license_number,registry_holder_name,account_name_before_verification INTO v FROM public.broker_license_verifications WHERE user_id=uid; IF v.license_number IS NULL THEN RAISE EXCEPTION 'registry_verification_required'; END IF; IF NOT public.official_license_exists(v.license_number) THEN RAISE EXCEPTION 'invalid_official_license'; END IF; SELECT id,certificate_name INTO c FROM public.broker_certificate_checks WHERE user_id=uid AND status='matched' AND license_number=v.license_number ORDER BY created_at DESC LIMIT 1; IF c.id IS NULL THEN RAISE EXCEPTION 'certificate_match_required'; END IF; auto_approve:=cardinality(public.broker_name_tokens(v.account_name_before_verification))>=2 AND public.broker_name_tokens(v.account_name_before_verification)=public.broker_name_tokens(v.registry_holder_name); outcome:=CASE WHEN auto_approve THEN 'approved' ELSE 'pending' END; SELECT id INTO request_id FROM public.broker_upgrade_requests WHERE user_id=uid AND status='pending'; IF request_id IS NULL THEN INSERT INTO public.broker_upgrade_requests(user_id,license_number,registry_holder_name,certificate_name,certificate_check_id,status,reviewed_at,review_note) VALUES(uid,v.license_number,v.registry_holder_name,c.certificate_name,c.id,outcome,CASE WHEN auto_approve THEN now() END,CASE WHEN auto_approve THEN 'auto_approved_name_match' END) RETURNING id INTO request_id; ELSE UPDATE public.broker_upgrade_requests SET license_number=v.license_number,registry_holder_name=v.registry_holder_name,certificate_name=c.certificate_name,certificate_check_id=c.id,created_at=now(),status=outcome,reviewed_at=CASE WHEN auto_approve THEN now() END,review_note=CASE WHEN auto_approve THEN 'auto_approved_name_match' END WHERE id=request_id; END IF; IF auto_approve THEN UPDATE public.profiles SET broker_license_number=v.license_number WHERE id=uid; INSERT INTO public.user_roles(user_id,role) VALUES(uid,'agent') ON CONFLICT(user_id,role) DO NOTHING; DELETE FROM public.broker_role_suspensions WHERE user_id=uid; END IF; INSERT INTO public.audit_logs(actor_id,action,target_table,target_id,details) VALUES(uid,CASE WHEN auto_approve THEN 'broker_upgrade_auto_approved' ELSE 'broker_upgrade_requested' END,'broker_upgrade_requests',request_id::text,jsonb_build_object('license_number',v.license_number,'status',outcome)); PERFORM public.notify_broker_upgrade(uid,request_id,outcome); RETURN jsonb_build_object('ok',true,'status',outcome,'id',request_id); END; $$;